<script lang="ts" module>

  import {  type NodeListEntry } from "$lib/database/evolu/queries";
  declare module "@sjsf/form" {
    interface UiOptions {
      nodeSelector?: {
        disabled?: (node: NodeListEntry) => boolean;
        nodeFilter?: (node: NodeListEntry) => boolean;
      };
    }

    interface WidgetsAndProps<V> {
      nodeSelector: {
        multiple: boolean;
        loading: boolean;
        processing: boolean;
      };
    }

    interface ComponentBindings {
      nodeSelector: "value";
    }
  }
</script>

<script lang="ts">
  import * as Select from "$lib/components/ui/select/index.js";
  import { getFormContext, type UiSchema } from "@sjsf/form";
  import { queryState } from "$lib/database/nodeRepository.svelte";
  import { getNodeList } from "$lib/database/evolu/queries";
  import { evolu } from "$lib/database/evolu/evolu_instance";
  import SvelteBoundary from "$lib/components/composites/SvelteBoundary.svelte";
  import type { JSONSchema7 } from "json-schema";

  let {
    value = $bindable(),
    config
  }: {
    value: string;
    config: {
      uiSchema: UiSchema
    }
  } = $props();

  const ctx = getFormContext();


  const allItemsList = queryState(() => getNodeList(), evolu, {
    useLoadQueryResult: true
  });


  const disabledFunction = $derived( config?.uiSchema?.["ui:options"]?.nodeSelector?.disabled ?? (() => false));
  const nodeFilterFunction = $derived( config?.uiSchema?.["ui:options"]?.nodeSelector?.nodeFilter ?? (() => true));

  let itemsByParent = $derived(allItemsList.rows.toSorted((a, b) => (a.order ?? 0) - (b.order ?? 0))
    .reduce((acc, item) => {
      const targetParentId = item.parentId ?? "root";

      if (!acc[targetParentId]) {
        acc[targetParentId] = [];
      }
      acc[targetParentId].push(item);
      return acc;
    }, {} as Record<string, NodeListEntry[]>));

  const nbsp = String.fromCharCode(160);

</script>

{#snippet labelOfItem (item: NodeListEntry)}
  Type: [{item.type}] {item.label}
{/snippet}

{#snippet itemsByParentSnippet (parentId: string, level = 0)}
  {#each itemsByParent[parentId].filter(nodeFilterFunction) as item, index}

    {#if level === 0 && index !== 0}
      <Select.Separator />
    {/if}

    <Select.Item value={item.id} disabled={disabledFunction(item)}>
      {''.padEnd(level * 2, nbsp)} {@render labelOfItem(item)} Dis: {disabledFunction(item)}
    </Select.Item>

    {#if itemsByParent[item.id]}
      {@render itemsByParentSnippet(item.id, level + 1)}
    {/if}

  {/each}
{/snippet}

<div class="w-[100%]">
  <SvelteBoundary>
    <Select.Root type="single" {value} onValueChange={(v) => value = v}>
      <Select.Trigger class="w-[100%]">
        {@const item = allItemsList.rows.find((item) => item.id === value)}
        {#if value && item}
          {@render labelOfItem(item)}
        {:else}
          Select a node
        {/if}
      </Select.Trigger>
      <Select.Content>
        {@render itemsByParentSnippet("root")}
      </Select.Content>
    </Select.Root>
  </SvelteBoundary>
</div>
